create or replace function hnk_private.validate_day068_completion_v2(p_evidence jsonb,p_expected_source_sha text)
returns void language plpgsql set search_path='' as $$
declare f jsonb;c jsonb;p jsonb;m jsonb;s jsonb;k text;r text;reason text;exit_reason text;score_key text;
begin
 if jsonb_typeof(p_evidence) is distinct from 'object' then raise exception 'day068_v2_evidence_object_required'; end if;
 if exists(select 1 from jsonb_object_keys(p_evidence) q where q not in ('protocol_version','source_sha','session_id','mode','fast','control','comparison','middle','private_vault_entry_ref','private_vault_e2ee_confirmed','practice_record_no_source_names_or_private_prose_confirmed','voluntary_completion_confirmed','final_safety_clear_confirmed','safety_stop_occurred','safety_stop_reason')) then raise exception 'day068_v2_unknown_top_field'; end if;
 if p_evidence->>'protocol_version' is distinct from 'HNK-CHOKMAH-D068-V2' then raise exception 'day068_v2_protocol_invalid'; end if;
 if p_evidence->>'source_sha' is distinct from p_expected_source_sha or p_expected_source_sha is distinct from '176ebffccc845a909f5d1d2bdb88181b94809afb' then raise exception 'day068_v2_source_sha_invalid'; end if;
 if nullif(btrim(p_evidence->>'session_id'),'') is null then raise exception 'day068_v2_session_required'; end if;
 if coalesce(p_evidence->>'mode','first_completion') not in ('first_completion','revisit') then raise exception 'day068_v2_mode_invalid'; end if;
 r:=p_evidence->>'private_vault_entry_ref';
 if r is not null and r!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then raise exception 'day068_v2_vault_ref_invalid'; end if;
 if r is not null and p_evidence->'private_vault_e2ee_confirmed' is distinct from 'true'::jsonb then raise exception 'day068_v2_vault_requires_e2ee'; end if;
 if r is null and p_evidence ? 'private_vault_e2ee_confirmed' and p_evidence->'private_vault_e2ee_confirmed' is not null and p_evidence->'private_vault_e2ee_confirmed' is distinct from 'false'::jsonb then raise exception 'day068_v2_e2ee_without_vault_ref'; end if;
 if p_evidence->'practice_record_no_source_names_or_private_prose_confirmed' is distinct from 'true'::jsonb or p_evidence->'voluntary_completion_confirmed' is distinct from 'true'::jsonb or p_evidence->'final_safety_clear_confirmed' is distinct from 'true'::jsonb then raise exception 'day068_v2_completion_boundary_missing'; end if;
 reason:=coalesce(p_evidence->>'safety_stop_reason','NONE'); if reason not in ('NONE','DISTRESS','ESSENTIAL_RESPONSIBILITY_RISK','SECURITY_OR_AUTH_RISK','OTHER') then raise exception 'day068_v2_safety_reason_invalid'; end if; if p_evidence->'safety_stop_occurred' is distinct from 'false'::jsonb or reason<>'NONE' then raise exception 'day068_v2_unresolved_safety_stop'; end if;
 f:=p_evidence->'fast'; if jsonb_typeof(f) is distinct from 'object' then raise exception 'day068_v2_fast_required'; end if;
 if exists(select 1 from jsonb_object_keys(f) q where q not in ('fast_seconds','sources_count','completed_confirmed','essential_exceptions_defined_confirmed','critical_alerts_preserved_confirmed','responsibilities_preserved_confirmed','early_exit_allowed_confirmed','early_exit_occurred','early_exit_reason','no_moral_purity_claim_confirmed','no_automatic_critical_blocking_confirmed','scores','impulsive_checks')) then raise exception 'day068_v2_fast_unknown_field'; end if;
 if not coalesce(hnk_private.jsonb_is_nonnegative_integer(f->'fast_seconds'),false) or (f->>'fast_seconds')::int<1 or (f->>'fast_seconds')::int>43200 then raise exception 'day068_v2_fast_duration_out_of_contract'; end if;
 if not coalesce(hnk_private.jsonb_is_nonnegative_integer(f->'sources_count'),false) or (f->>'sources_count')::int<>3 then raise exception 'day068_v2_exact_three_sources_required'; end if;
 foreach k in array array['completed_confirmed','essential_exceptions_defined_confirmed','critical_alerts_preserved_confirmed','responsibilities_preserved_confirmed','early_exit_allowed_confirmed','no_moral_purity_claim_confirmed','no_automatic_critical_blocking_confirmed'] loop if f->k is distinct from 'true'::jsonb then raise exception 'day068_v2_fast_boundary_required:%',k; end if; end loop;
 if jsonb_typeof(f->'early_exit_occurred') is distinct from 'boolean' then raise exception 'day068_v2_early_exit_flag_invalid'; end if;
 exit_reason:=coalesce(f->>'early_exit_reason','NONE'); if exit_reason not in ('NONE','ESSENTIAL_COMMUNICATION','WORK','FAMILY','SECURITY_AUTH','OTHER') then raise exception 'day068_v2_early_exit_reason_invalid'; end if;
 if f->'early_exit_occurred'='true'::jsonb and exit_reason='NONE' then raise exception 'day068_v2_early_exit_reason_required'; end if; if f->'early_exit_occurred'='false'::jsonb and exit_reason<>'NONE' then raise exception 'day068_v2_early_exit_reason_without_exit'; end if;
 if not coalesce(hnk_private.jsonb_is_nonnegative_integer(f->'impulsive_checks'),false) then raise exception 'day068_v2_impulsive_checks_invalid'; end if;
 s:=f->'scores'; if jsonb_typeof(s) is distinct from 'object' or exists(select 1 from jsonb_object_keys(s) q where q not in ('anxiety_before','checking_urge_before','focus_after','mood_after')) then raise exception 'day068_v2_fast_scores_invalid'; end if;
 foreach score_key in array array['anxiety_before','checking_urge_before','focus_after','mood_after'] loop if not coalesce(hnk_private.jsonb_is_nonnegative_integer(s->score_key),false) or (s->>score_key)::int>10 then raise exception 'day068_v2_fast_score_invalid:%',score_key; end if; end loop;
 c:=p_evidence->'control'; if jsonb_typeof(c) is distinct from 'object' then raise exception 'day068_v2_control_required'; end if;
 if exists(select 1 from jsonb_object_keys(c) q where q not in ('control_seconds','completed_confirmed','comparable_other_day_confirmed','normal_use_no_behavior_improvement_confirmed','scores','unlocks','feed_minutes')) then raise exception 'day068_v2_control_unknown_field'; end if;
 if not coalesce(hnk_private.jsonb_is_nonnegative_integer(c->'control_seconds'),false) or (c->>'control_seconds')::int<1 or (c->>'control_seconds')::int>43200 then raise exception 'day068_v2_control_duration_out_of_contract'; end if;
 foreach k in array array['completed_confirmed','comparable_other_day_confirmed','normal_use_no_behavior_improvement_confirmed'] loop if c->k is distinct from 'true'::jsonb then raise exception 'day068_v2_control_boundary_required:%',k; end if; end loop;
 foreach k in array array['unlocks','feed_minutes'] loop if not coalesce(hnk_private.jsonb_is_nonnegative_integer(c->k),false) then raise exception 'day068_v2_control_metric_invalid:%',k; end if; end loop;
 s:=c->'scores'; if jsonb_typeof(s) is distinct from 'object' or exists(select 1 from jsonb_object_keys(s) q where q not in ('anxiety','focus','decision_quality')) then raise exception 'day068_v2_control_scores_invalid'; end if;
 foreach score_key in array array['anxiety','focus','decision_quality'] loop if not coalesce(hnk_private.jsonb_is_nonnegative_integer(s->score_key),false) or (s->>score_key)::int>10 then raise exception 'day068_v2_control_score_invalid:%',score_key; end if; end loop;
 p:=p_evidence->'comparison'; if jsonb_typeof(p) is distinct from 'object' then raise exception 'day068_v2_comparison_required'; end if;
 if exists(select 1 from jsonb_object_keys(p) q where q not in ('completed_confirmed','after_both_windows_confirmed','no_winner_declared_confirmed','null_or_control_better_result_valid_confirmed','egregore_metaphor_not_literalized_confirmed','no_single_cause_claim_confirmed','routine_sleep_work_confounds_considered_confirmed','communication_harm_triggers_rule_adjustment_confirmed','information_and_responsibility_preserved_confirmed','sustainable_rule_defined_confirmed','review_days')) then raise exception 'day068_v2_comparison_unknown_field'; end if;
 foreach k in array array['completed_confirmed','after_both_windows_confirmed','no_winner_declared_confirmed','null_or_control_better_result_valid_confirmed','egregore_metaphor_not_literalized_confirmed','no_single_cause_claim_confirmed','routine_sleep_work_confounds_considered_confirmed','communication_harm_triggers_rule_adjustment_confirmed','information_and_responsibility_preserved_confirmed','sustainable_rule_defined_confirmed'] loop if p->k is distinct from 'true'::jsonb then raise exception 'day068_v2_comparison_boundary_required:%',k; end if; end loop;
 if not coalesce(hnk_private.jsonb_is_nonnegative_integer(p->'review_days'),false) or (p->>'review_days')::int<>7 then raise exception 'day068_v2_review_days_invalid'; end if;
 m:=p_evidence->'middle'; if jsonb_typeof(m) is distinct from 'object' then raise exception 'day068_v2_middle_required'; end if;
 if exists(select 1 from jsonb_object_keys(m) q where q not in ('psalm_9_9_confirmed','mem_bet_he_confirmed','source_to_limit_named_count','source_to_keep_named_count','responsibility_not_silenced_named_count','thanks_to_god_confirmed','deliberate_reconnection_confirmed','seven_day_rule_confirmed','return_confirmed')) then raise exception 'day068_v2_middle_unknown_field'; end if;
 foreach k in array array['psalm_9_9_confirmed','mem_bet_he_confirmed','thanks_to_god_confirmed','deliberate_reconnection_confirmed','seven_day_rule_confirmed','return_confirmed'] loop if m->k is distinct from 'true'::jsonb then raise exception 'day068_v2_middle_boundary_required:%',k; end if; end loop;
 foreach k in array array['source_to_limit_named_count','source_to_keep_named_count','responsibility_not_silenced_named_count'] loop if not coalesce(hnk_private.jsonb_is_nonnegative_integer(m->k),false) or (m->>k)::int<>1 then raise exception 'day068_v2_middle_exactly_one_required:%',k; end if; end loop;
 perform hnk_private.validate_day068_scalar_evidence_v1(jsonb_build_object('protocol_completed',true,'return_confirmed',m->'return_confirmed','three_sources_identified',true,'essential_exceptions_defined',f->'essential_exceptions_defined_confirmed','fast_completed',f->'completed_confirmed','control_completed',c->'completed_confirmed','comparison_completed',p->'completed_confirmed','early_exit_allowed',f->'early_exit_allowed_confirmed','critical_alerts_preserved',f->'critical_alerts_preserved_confirmed','responsibilities_preserved',f->'responsibilities_preserved_confirmed','egregore_not_literalized',p->'egregore_metaphor_not_literalized_confirmed','sustainable_rule_defined',p->'sustainable_rule_defined_confirmed','vault_saved',true,'safety_clear',p_evidence->'final_safety_clear_confirmed','sources_count',f->'sources_count','fast_seconds',f->'fast_seconds','control_seconds',c->'control_seconds'));
end $$;

create or replace function hnk_private.enforce_mebahel_067_071_scalar_evidence()
returns trigger language plpgsql security definer set search_path='' as $$
declare existing boolean; sha text; st text; begin
 if new.day not in (67,68,69,70,71) or new.state not in ('evidence_pending','complete') then return new; end if;
 select exists(select 1 from public.day_completions where user_id=new.user_id and day=new.day) into existing; if existing then return new; end if;
 select source_sha,status into sha,st from public.codex_days where day=new.day; if st is distinct from 'canon' then raise exception 'mebahel_canonical_day_not_available'; end if;
 if new.day=67 then if sha is distinct from '1fe06968c724f74311e4fd567075fabc181f1125' then raise exception 'day067_canonical_source_sha_mismatch'; end if; if new.evidence->>'protocol_version'='HNK-CHOKMAH-D067-V2' then perform hnk_private.validate_day067_completion_v2(new.evidence,sha); else perform hnk_private.validate_day067_scalar_evidence_v1(new.evidence); end if;
 elsif new.day=68 then if sha is distinct from '176ebffccc845a909f5d1d2bdb88181b94809afb' then raise exception 'day068_canonical_source_sha_mismatch'; end if; if new.evidence->>'protocol_version'='HNK-CHOKMAH-D068-V2' then perform hnk_private.validate_day068_completion_v2(new.evidence,sha); else perform hnk_private.validate_day068_scalar_evidence_v1(new.evidence); end if;
 elsif new.day=69 then if sha is distinct from '5ec5e7ade94e1a20c348028d75517475a6920e5a' then raise exception 'day069_canonical_source_sha_mismatch'; end if; perform hnk_private.validate_day069_scalar_evidence_v1(new.evidence);
 elsif new.day=70 then if sha is distinct from 'bb1e47aee510fe9df58a46f697ebafb9005e223e' then raise exception 'day070_canonical_source_sha_mismatch'; end if; perform hnk_private.validate_day070_scalar_evidence_v1(new.evidence);
 else if sha is distinct from '6dfa6b5768bd7cdc2812d5dbfc68a8bc66ad90c3' then raise exception 'day071_canonical_source_sha_mismatch'; end if; perform hnk_private.validate_day071_scalar_evidence_v1(new.evidence); end if;
 return new;
end $$;

do $$ declare d text; begin d:=pg_get_functiondef('hnk_private.validate_completion_contract_v2(text,jsonb,text)'::regprocedure); if position('when ''day068_v2''' in d)=0 then d:=replace(d,'else raise exception ''unsupported_completion_validator:%'',p_validator_key;','when ''day068_v2'' then perform hnk_private.validate_day068_completion_v2(p_evidence,p_expected_source_sha);'||chr(10)||'  else raise exception ''unsupported_completion_validator:%'',p_validator_key;'); if position('when ''day068_v2''' in d)=0 then raise exception 'day068_dispatcher_patch_failed'; end if; execute d; end if; end $$;

insert into hnk_private.completion_contract_registry(completion_contract_id,quest_definition_id,day,canonical_source_sha,contract_version,validator_key,status)
values('HNK-CHOKMAH-D068-COMP-V2','HNK-CHOKMAH-D068-V2',68,'176ebffccc845a909f5d1d2bdb88181b94809afb','2.0.0','day068_v2','draft')
on conflict(completion_contract_id) do update set quest_definition_id=excluded.quest_definition_id,day=excluded.day,canonical_source_sha=excluded.canonical_source_sha,contract_version=excluded.contract_version,validator_key=excluded.validator_key,status='draft',updated_at=now();
